assert len(DATA) == 10
TARGETS = ["A", "B", "A", "B", "B", "B", "A", "A", "B", "A"]
for i, (prompt, options, answer, explanation, strategy, steps) in enumerate(DATA, 1):
    target = TARGETS[i - 1]
    if target != "A":
        ti = ord(target) - ord("A")
        options = options[1:ti + 1] + [options[0]] + options[ti + 1:]
        explanation = explanation.replace("A ", f"{target} ")
        strategy = strategy.replace("A ", f"{target} ")
        steps = [s.replace("A ", f"{target} ") for s in steps]
        answer = target
